SELECT sp.subject_id, COUNT(*) AS medication_complexity_score, percent_rank() OVER (ORDER BY COUNT(*)) AS percentile_rank, (sp.stay_length_of_stay - 24) AS length_of_stay, CASE WHEN sp.dod IS NOT NULL THEN 1 ELSE 0 END AS mortality_flag FROM sepsis_patients sp JOIN admissions a ON sp.subject_id = a.subject_id JOIN pharmacy ph ON a.subject_id = ph.subject_id JOIN prescriptions pr ON ph.subject_id = pr.subject_id WHERE a.stay_length_of_stay <= 24 AND (pr.drug_type = 'QT prolonging' OR pr.drug_type = 'bleeding risk') GROUP BY sp.subject_id ORDER BY medication_complexity_score NULLS LAST;